BEGIN
  DECLARE v_nota DECIMAL(4,2);
  DECLARE v_total INT DEFAULT 0;
  DECLARE v_max DECIMAL(4,2) DEFAULT 0;
  DECLARE v_min DECIMAL(4,2) DEFAULT 10;
  DECLARE v_suma DECIMAL(6,2) DEFAULT 0;
  DECLARE v_i INT DEFAULT 1;
  DECLARE v_count INT DEFAULT 0;
  SELECT COUNT(*) INTO v_count FROM notas WHERE id_alumno = 1;
  WHILE v_i <= v_count DO
    SELECT nota INTO v_nota FROM notas WHERE id_alumno = 1 LIMIT 1 OFFSET v_i - 1;
    SET v_total = v_total + 1;
    SET v_suma = v_suma + v_nota;
    IF v_nota > v_max THEN SET v_max = v_nota; END IF;
    IF v_nota < v_min THEN SET v_min = v_nota; END IF;
    SET v_i = v_i + 1;
  END WHILE;
  SELECT v_total, v_max, v_min, ROUND(v_suma/v_total, 2) AS media;
END;
```

