  FROM asignaturas asig LEFT JOIN profesores p ON asig.id_profesor = p.id WHERE asig.ciclo = p_ciclo;
  SELECT asig.nombre, ROUND(AVG(n.nota),2) AS media
  FROM asignaturas asig LEFT JOIN notas n ON asig.id = n.id_asignatura WHERE asig.ciclo = p_ciclo GROUP BY asig.id;
END //
DELIMITER ;
```

