## Rutina 3: Clasificar disponibilidad (CASE)

```sql
DELIMITER //
CREATE PROCEDURE sp_clasificar_disponibilidad(IN p_id_asignatura INT)
BEGIN
  DECLARE v_total INT DEFAULT 0;
  DECLARE v_nombre VARCHAR(100);
  DECLARE v_clase VARCHAR(30);
  SELECT nombre INTO v_nombre FROM asignaturas WHERE id = p_id_asignatura;
  SELECT COUNT(*) INTO v_total FROM matriculas
  WHERE id_asignatura = p_id_asignatura AND estado = 'activa';
  CASE
    WHEN v_total >= 30 THEN SET v_clase = 'Lleno';
    WHEN v_total >= 20 THEN SET v_clase = 'Casi lleno';
