## Rutina 5: Estadísticas con WHILE

```sql
DELIMITER //
CREATE PROCEDURE sp_estadisticas_bucle(
  IN p_id_alumno INT, OUT p_max DECIMAL(4,2), OUT p_min DECIMAL(4,2))
BEGIN
  DECLARE v_i INT DEFAULT 1;
  DECLARE v_count INT DEFAULT 0;
  DECLARE v_nota DECIMAL(4,2);
  SET p_max = 0; SET p_min = 10;
  SELECT COUNT(*) INTO v_count FROM notas WHERE id_alumno = p_id_alumno;
  WHILE v_i <= v_count DO
    SELECT nota INTO v_nota FROM notas WHERE id_alumno = p_id_alumno LIMIT 1 OFFSET v_i - 1;
    IF v_nota > p_max THEN SET p_max = v_nota; END IF;
    IF v_nota < p_min THEN SET p_min = v_nota; END IF;
    SET v_i = v_i + 1;
  END WHILE;
END //
DELIMITER ;

CALL sp_estadisticas_bucle(1, @max, @min);
SELECT @max AS nota_maxima, @min AS nota_minima;
```

